from pathlib import Path


def replace_once(source: str, old: str, new: str, label: str) -> str:
    if source.count(old) != 1:
        raise RuntimeError(f"{label}_match_count:{source.count(old)}")
    return source.replace(old, new, 1)


path = Path("ai_test_asset_center/process_step_execution.py")
source = path.read_text(encoding="utf-8")
source = replace_once(source, 'SEMANTIC_TRANSPORT_FAILED = "TRANSPORT_FAILED"\nSEMANTIC_BLOCKED = "BLOCKED"', 'SEMANTIC_TRANSPORT_FAILED = "TRANSPORT_FAILED"\nSEMANTIC_OPERATION_REJECTED = "OPERATION_REJECTED"\nSEMANTIC_BLOCKED = "BLOCKED"', "semantic_operation_rejected_constant")
source = replace_once(source, '''def _semantic_step_status(\n    *,\n    final_status: str,\n    operation_accepted: bool,\n    target_state_observed: bool,\n    target_reached: bool | None,\n) -> str:\n    if final_status == "BLOCKED":\n        return SEMANTIC_BLOCKED\n    if final_status == "FAILED":\n        return SEMANTIC_FAILED\n    if not operation_accepted:\n        return SEMANTIC_TRANSPORT_FAILED\n    if not target_state_observed:\n        return SEMANTIC_PENDING_OBSERVATION\n    return (\n        SEMANTIC_TARGET_REACHED\n        if target_reached is True\n        else SEMANTIC_TARGET_NOT_REACHED\n    )\n''', '''def _semantic_step_status(\n    *,\n    final_status: str,\n    response_received: bool,\n    operation_accepted: bool,\n    target_state_observed: bool,\n    target_reached: bool | None,\n) -> str:\n    if final_status == "BLOCKED":\n        return SEMANTIC_BLOCKED\n    if not response_received:\n        return SEMANTIC_TRANSPORT_FAILED\n    if not operation_accepted:\n        return SEMANTIC_OPERATION_REJECTED\n    if final_status == "FAILED":\n        return SEMANTIC_FAILED\n    if not target_state_observed:\n        return SEMANTIC_PENDING_OBSERVATION\n    return (\n        SEMANTIC_TARGET_REACHED\n        if target_reached is True\n        else SEMANTIC_TARGET_NOT_REACHED\n    )\n''', "semantic_status_function")
source = replace_once(source, '''        final_status: str = "EXECUTED",\n        mutation_occurred: bool | None = None,\n        target_reached: bool | None = None,\n    ) -> dict[str, Any]:''', '''        final_status: str = "EXECUTED",\n        mutation_occurred: bool | None = None,\n        operation_accepted: bool | None = None,\n        business_effect_observed: bool | None = None,\n        target_reached: bool | None = None,\n    ) -> dict[str, Any]:''', "record_signature")
source = replace_once(source, '''        operation_accepted = _operation_accepted(observed_status, normalized_final)\n        target_state_observed = (\n            target_reached is not None and bool(independent_state_receipts)\n        )\n        reached: bool | None = (\n            bool(target_reached) if target_state_observed else None\n        )\n        semantic_status = _semantic_step_status(\n            final_status=normalized_final,\n            operation_accepted=operation_accepted,\n            target_state_observed=target_state_observed,\n            target_reached=reached,\n        )\n        step_completed = semantic_status == SEMANTIC_TARGET_REACHED\n        step_failed = semantic_status in {\n            SEMANTIC_TARGET_NOT_REACHED,\n            SEMANTIC_TRANSPORT_FAILED,\n            SEMANTIC_BLOCKED,\n            SEMANTIC_FAILED,\n        }\n''', '''        response_received = observed_status > 0 or bool(response_id)\n        transport_attempted = bool(\n            _text(request_receipt_id)\n            or _text(transport_receipt_id)\n            or response_received\n        )\n        accepted = (\n            operation_accepted\n            if isinstance(operation_accepted, bool)\n            else _operation_accepted(observed_status, normalized_final)\n        )\n        target_state_observed = (\n            target_reached is not None and bool(independent_state_receipts)\n        )\n        effect_observed = (\n            bool(business_effect_observed)\n            if isinstance(business_effect_observed, bool)\n            and bool(independent_state_receipts)\n            else target_state_observed\n        )\n        reached: bool | None = (\n            bool(target_reached) if target_state_observed else None\n        )\n        semantic_status = _semantic_step_status(\n            final_status=normalized_final,\n            response_received=response_received,\n            operation_accepted=accepted,\n            target_state_observed=target_state_observed,\n            target_reached=reached,\n        )\n        step_completed = semantic_status == SEMANTIC_TARGET_REACHED\n        step_failed = semantic_status in {\n            SEMANTIC_TARGET_NOT_REACHED,\n            SEMANTIC_TRANSPORT_FAILED,\n            SEMANTIC_OPERATION_REJECTED,\n            SEMANTIC_BLOCKED,\n            SEMANTIC_FAILED,\n        }\n''', "record_fact_derivation")
source = replace_once(source, '''            "transport_started": now,\n            "transport_completed": now,\n            "response_received": observed_status > 0 or bool(response_id),\n            "operation_accepted": operation_accepted,\n            "business_effect_observed": target_state_observed,\n''', '''            "transport_attempted": transport_attempted,\n            "transport_started": now if transport_attempted else None,\n            "transport_completed": now if response_received else None,\n            "transport_failed": bool(transport_attempted and not response_received),\n            "response_received": response_received,\n            "operation_accepted": accepted,\n            "business_effect_observed": effect_observed,\n''', "row_transport_facts")
source = replace_once(source, '''    def executed_step_ids(self) -> list[str]:\n        return [\n            sid\n            for sid, row in self._rows.items()\n            if row.get("semantic_step_status") == SEMANTIC_TARGET_REACHED\n        ]\n\n    def successful_write_step_ids(self) -> list[str]:\n        return [\n            sid\n            for sid, row in self._rows.items()\n            if row.get("operation_accepted") is True\n            and row.get("semantic_step_status") == SEMANTIC_TARGET_REACHED\n            and row.get("mutation_occurred") is not False\n        ]\n''', '''    def attempted_step_ids(self) -> list[str]:\n        return [\n            sid\n            for sid, row in self._rows.items()\n            if row.get("transport_attempted") is True\n        ]\n\n    def executed_step_ids(self) -> list[str]:\n        """Steps that reached a target transport and received a response.\n\n        This is deliberately independent from semantic completion. A 4xx/5xx\n        response is still a real execution attempt and must remain available to\n        Oracle, evidence-completeness, and bug-discovery accounting.\n        """\n        return [\n            sid\n            for sid, row in self._rows.items()\n            if row.get("response_received") is True\n            and _text(row.get("final_status")).upper() == "EXECUTED"\n        ]\n\n    def completed_step_ids(self) -> list[str]:\n        return [\n            sid\n            for sid, row in self._rows.items()\n            if row.get("semantic_step_status") == SEMANTIC_TARGET_REACHED\n        ]\n\n    def accepted_step_ids(self) -> list[str]:\n        return [\n            sid\n            for sid, row in self._rows.items()\n            if row.get("operation_accepted") is True\n        ]\n\n    def successful_write_step_ids(self) -> list[str]:\n        return [\n            sid\n            for sid, row in self._rows.items()\n            if row.get("operation_accepted") is True\n            and row.get("mutation_occurred") is not False\n        ]\n''', "ledger_step_sets")
source = replace_once(source, '''    target["executed_step_ids"] = list(ledger.executed_step_ids())\n    target["recorded_step_ids"] = list(ledger.recorded_step_ids())\n''', '''    target["attempted_step_ids"] = list(ledger.attempted_step_ids())\n    target["executed_step_ids"] = list(ledger.executed_step_ids())\n    target["accepted_step_ids"] = list(ledger.accepted_step_ids())\n    target["completed_step_ids"] = list(ledger.completed_step_ids())\n    target["recorded_step_ids"] = list(ledger.recorded_step_ids())\n''', "attach_step_sets")
source = replace_once(source, '''    expected = set(_unique_texts(expected_step_ids))\n    executed = set(ledger.executed_step_ids())\n    failed = set(ledger.failed_step_ids())\n    skipped = expected - executed\n    if failed:\n        result = PROCESS_FAILED\n    elif expected and executed == expected and evidence_complete:\n        result = PROCESS_COMPLETED\n    elif executed and not evidence_complete:\n        result = PROCESS_EVIDENCE_INCOMPLETE\n    elif executed and skipped:\n        result = PROCESS_PARTIALLY_EXECUTED\n    else:\n        result = PROCESS_FAILED\n    return {\n        "schema_version": COMPLETION_ORACLE_SCHEMA,\n        "experiment_id": experiment_id or ledger.experiment_id,\n        "result": result,\n        "expected_step_ids": sorted(expected),\n        "executed_step_ids": sorted(executed),\n        "completed_step_ids": sorted(executed),\n''', '''    expected = set(_unique_texts(expected_step_ids))\n    executed = set(ledger.executed_step_ids())\n    completed = set(ledger.completed_step_ids())\n    failed = set(ledger.failed_step_ids())\n    skipped = expected - executed\n    if failed:\n        result = PROCESS_FAILED\n    elif expected and completed == expected and evidence_complete:\n        result = PROCESS_COMPLETED\n    elif executed and not evidence_complete:\n        result = PROCESS_EVIDENCE_INCOMPLETE\n    elif executed and (skipped or completed != expected):\n        result = PROCESS_PARTIALLY_EXECUTED\n    else:\n        result = PROCESS_FAILED\n    return {\n        "schema_version": COMPLETION_ORACLE_SCHEMA,\n        "experiment_id": experiment_id or ledger.experiment_id,\n        "result": result,\n        "expected_step_ids": sorted(expected),\n        "executed_step_ids": sorted(executed),\n        "completed_step_ids": sorted(completed),\n''', "process_completion_sets")
path.write_text(source, encoding="utf-8")

path = Path("ai_test_asset_center/process_step_semantic_projection.py")
source = path.read_text(encoding="utf-8")
source = replace_once(source, '''    recorded: list[str] = []\n    accepted: list[str] = []\n    completed: list[str] = []\n''', '''    recorded: list[str] = []\n    attempted: list[str] = []\n    executed: list[str] = []\n    accepted: list[str] = []\n    completed: list[str] = []\n''', "projection_lists")
source = replace_once(source, '''        recorded.append(step_id)\n        is_accepted = _accepted(row)\n''', '''        recorded.append(step_id)\n        response_received = row.get("response_received") is True\n        transport_attempted = (\n            row.get("transport_attempted") is True\n            or response_received\n            or bool(_text(row.get("request_receipt_id")))\n            or bool(_text(row.get("transport_receipt_id")))\n        )\n        if transport_attempted:\n            attempted.append(step_id)\n        if (\n            response_received\n            and _text(row.get("final_status")).upper() == "EXECUTED"\n        ):\n            executed.append(step_id)\n        is_accepted = _accepted(row)\n''', "projection_transport")
source = replace_once(source, '''        "recorded_step_ids": recorded,\n        "accepted_step_ids": accepted,\n''', '''        "recorded_step_ids": recorded,\n        "attempted_step_ids": attempted,\n        "executed_step_ids": executed,\n        "accepted_step_ids": accepted,\n''', "projection_return")
path.write_text(source, encoding="utf-8")

path = Path("ai_test_asset_center/process_step_semantic_view.py")
source = path.read_text(encoding="utf-8")
source = replace_once(source, '''    def executed_step_ids(self) -> list[str]:\n        self._synchronize()\n        return project_step_sets(self._ledger)["completed_step_ids"]\n\n    def failed_step_ids(self) -> list[str]:''', '''    def attempted_step_ids(self) -> list[str]:\n        self._synchronize()\n        return project_step_sets(self._ledger)["attempted_step_ids"]\n\n    def executed_step_ids(self) -> list[str]:\n        self._synchronize()\n        return project_step_sets(self._ledger)["executed_step_ids"]\n\n    def completed_step_ids(self) -> list[str]:\n        self._synchronize()\n        return project_step_sets(self._ledger)["completed_step_ids"]\n\n    def accepted_step_ids(self) -> list[str]:\n        self._synchronize()\n        return project_step_sets(self._ledger)["accepted_step_ids"]\n\n    def failed_step_ids(self) -> list[str]:''', "semantic_view_sets")
path.write_text(source, encoding="utf-8")

test = '''from ai_test_asset_center.process_step_execution import (\n    PROCESS_EVIDENCE_INCOMPLETE,\n    PROCESS_FAILED,\n    ProcessStepLedger,\n    attach_ledger_refs_to_observations,\n    evaluate_per_step_evidence_completeness,\n    evaluate_process_completion,\n)\nfrom ai_test_asset_center.process_step_semantic_projection import (\n    apply_semantic_verdict,\n    project_step_sets,\n)\nfrom ai_test_asset_center.process_step_semantic_view import ProcessStepSemanticView\n\n\ndef _ledger():\n    return ProcessStepLedger("experiment-1", required_step_ids=["step-1"])\n\n\ndef _record(ledger, *, status=200, final="EXECUTED", response=True, mutation=None):\n    return ledger.record_step_execution(\n        step_id="step-1", phase="treatment", operation_ref="op-1",\n        actor_ref="actor-1", request_receipt_id="request-1",\n        response_receipt_id="response-1" if response else "",\n        status_code=status, final_status=final, mutation_occurred=mutation,\n    )\n\n\ndef test_http_rejection_is_executed_not_accepted_or_completed():\n    ledger = _ledger(); row = _record(ledger, status=404)\n    assert row["transport_attempted"] is True\n    assert row["response_received"] is True\n    assert row["operation_accepted"] is False\n    assert row["semantic_step_status"] == "OPERATION_REJECTED"\n    assert row["step_completed"] is False and row["step_failed"] is True\n    assert ledger.executed_step_ids() == ["step-1"]\n    assert ledger.completed_step_ids() == []\n\n\ndef test_accepted_without_observation_is_not_business_completion():\n    ledger = _ledger(); row = _record(ledger)\n    assert row["operation_accepted"] is True\n    assert row["business_effect_observed"] is False\n    assert row["semantic_step_status"] == "PENDING_OBSERVATION"\n    assert ledger.executed_step_ids() == ["step-1"]\n    assert ledger.accepted_step_ids() == ["step-1"]\n    assert ledger.completed_step_ids() == []\n    evidence = evaluate_per_step_evidence_completeness(planned_step_ids=["step-1"], ledger=ledger)\n    assert evidence["missing_execution"] == []\n    assert evidence["missing_observation"] == ["step-1"]\n\n\ndef test_scoped_target_verdict_completes_business_step():\n    ledger = _ledger(); _record(ledger)\n    assert apply_semantic_verdict(ledger, step_id="step-1", receipt_step_id="step-1", receipt_id="observer-1", source="state_observer", target_reached=True)\n    assert ledger.executed_step_ids() == ["step-1"]\n    assert ledger.completed_step_ids() == ["step-1"]\n    projection = project_step_sets(ledger)\n    assert projection["executed_step_ids"] == ["step-1"]\n    assert projection["completed_step_ids"] == ["step-1"]\n\n\ndef test_semantic_view_keeps_execution_separate_from_completion():\n    ledger = _ledger(); _record(ledger); view = ProcessStepSemanticView(ledger)\n    assert view.executed_step_ids() == ["step-1"]\n    assert view.completed_step_ids() == []\n\n\ndef test_accepted_write_requires_cleanup_before_target_observation():\n    ledger = _ledger(); _record(ledger, status=202, mutation=True)\n    assert ledger.successful_write_step_ids() == ["step-1"]\n    assert ledger.completed_step_ids() == []\n\n\ndef test_no_response_is_transport_failure_not_operation_rejection():\n    ledger = _ledger(); row = _record(ledger, status=0, final="FAILED", response=False)\n    assert row["transport_attempted"] is True\n    assert row["response_received"] is False\n    assert row["transport_failed"] is True\n    assert row["semantic_step_status"] == "TRANSPORT_FAILED"\n    assert ledger.attempted_step_ids() == ["step-1"]\n    assert ledger.executed_step_ids() == []\n\n\ndef test_process_completion_uses_business_completion():\n    ledger = _ledger(); _record(ledger)\n    outcome = evaluate_process_completion(expected_step_ids=["step-1"], ledger=ledger, evidence_complete=False)\n    assert outcome["result"] == PROCESS_EVIDENCE_INCOMPLETE\n    assert outcome["executed_step_ids"] == ["step-1"]\n    assert outcome["completed_step_ids"] == []\n\n\ndef test_false_verdict_is_failed_never_completed_and_failed():\n    ledger = _ledger(); _record(ledger)\n    apply_semantic_verdict(ledger, step_id="step-1", receipt_step_id="step-1", receipt_id="oracle-1", source="oracle", target_reached=False)\n    row = ledger.get_step_row("step-1")\n    assert row["step_completed"] is False and row["step_failed"] is True\n    outcome = evaluate_process_completion(expected_step_ids=["step-1"], ledger=ledger, evidence_complete=True)\n    assert outcome["result"] == PROCESS_FAILED\n\n\ndef test_observations_export_distinct_step_sets():\n    ledger = _ledger(); _record(ledger)\n    observations = attach_ledger_refs_to_observations({}, ledger)\n    assert observations["attempted_step_ids"] == ["step-1"]\n    assert observations["executed_step_ids"] == ["step-1"]\n    assert observations["accepted_step_ids"] == ["step-1"]\n    assert observations["completed_step_ids"] == []\n'''
Path("tests/test_process_step_fact_separation.py").write_text(test, encoding="utf-8")
